create table if not exists public.erp_postos_trabalho(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,codigo_posto varchar(20) not null,nome_posto varchar(100) not null,taxa_hora numeric(10,2) not null default 0,ativo boolean not null default true,criado_em timestamptz not null default now(),unique(empresa_id,codigo_posto));
create table if not exists public.erp_pcp_bom_itens(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,produto_pai_id uuid not null,produto_id uuid not null,sku_insumo text not null,qtd numeric(18,6) not null check(qtd>0),unidade text not null,custo_unitario numeric(18,6) not null default 0,created_at timestamptz not null default now());
create table if not exists public.erp_pcp_roteiro_operacoes(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,produto_id uuid not null,sequencia integer not null,operacao text not null,posto_id uuid not null references public.erp_postos_trabalho(id),tempo_min numeric(12,3) not null default 0,created_at timestamptz not null default now());
create table if not exists public.erp_pcp_apontamentos_turno(id uuid primary key default gen_random_uuid(),empresa_id uuid not null,operador_auth_id uuid not null,cracha text not null,evento text not null,criado_em timestamptz not null default now());
alter table public.erp_postos_trabalho enable row level security;alter table public.erp_pcp_bom_itens enable row level security;alter table public.erp_pcp_roteiro_operacoes enable row level security;alter table public.erp_pcp_apontamentos_turno enable row level security;
create policy pcp_postos_all on public.erp_postos_trabalho for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy pcp_bom_all on public.erp_pcp_bom_itens for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy pcp_roteiro_all on public.erp_pcp_roteiro_operacoes for all to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master()) with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy pcp_apont_select on public.erp_pcp_apontamentos_turno for select to authenticated using(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create policy pcp_apont_insert on public.erp_pcp_apontamentos_turno for insert to authenticated with check(empresa_id=public.erp_current_empresa_id() or public.erp_is_master());
create or replace function public.erp_pcp_salvar_posto(p_codigo_posto text,p_nome_posto text,p_taxa_hora numeric) returns uuid language plpgsql security invoker set search_path=public as $$declare e uuid;v uuid;begin e:=erp_current_empresa_id();if e is null and not erp_is_master() then raise exception 'Empresa não identificada';end if;insert into erp_postos_trabalho(empresa_id,codigo_posto,nome_posto,taxa_hora) values(e,btrim(p_codigo_posto),btrim(p_nome_posto),p_taxa_hora) on conflict(empresa_id,codigo_posto) do update set nome_posto=excluded.nome_posto,taxa_hora=excluded.taxa_hora,ativo=true returning id into v;return v;end$$;
create or replace function public.erp_pcp_bom_adicionar(p_produto_pai_id uuid,p_produto_id uuid,p_sku_insumo text,p_qtd numeric,p_unidade text,p_custo_unitario numeric) returns uuid language plpgsql security invoker set search_path=public as $$declare e uuid;v uuid;begin e:=erp_current_empresa_id();if e is null and not erp_is_master() then raise exception 'Empresa não identificada';end if;insert into erp_pcp_bom_itens(empresa_id,produto_pai_id,produto_id,sku_insumo,qtd,unidade,custo_unitario) values(e,p_produto_pai_id,p_produto_id,p_sku_insumo,p_qtd,p_unidade,p_custo_unitario) returning id into v;return v;end$$;
revoke all on function public.erp_pcp_salvar_posto(text,text,numeric) from public,anon;grant execute on function public.erp_pcp_salvar_posto(text,text,numeric) to authenticated;
revoke all on function public.erp_pcp_bom_adicionar(uuid,uuid,text,numeric,text,numeric) from public,anon;grant execute on function public.erp_pcp_bom_adicionar(uuid,uuid,text,numeric,text,numeric) to authenticated;
grant select,insert,update,delete on public.erp_postos_trabalho,public.erp_pcp_bom_itens,public.erp_pcp_roteiro_operacoes,public.erp_pcp_apontamentos_turno to authenticated;